mapper.select:
SELECT u.id AS id, u.role AS userType, u.username AS username, u.real_name AS realName, u.phone AS phone, u.status AS status, u.created_at AS createdAt, d.audit_status AS auditStatus, d.audit_remark AS auditRemark, d.department AS department, d.title AS title, d.expertise_tags AS expertiseTags, d.license_no AS licenseNo, a.admin_level AS adminLevel, r.gender AS gender, r.birth_year AS birthYear FROM sys_user u LEFT JOIN `user` r ON r.id = u.id LEFT JOIN doctor d ON d.id = u.id LEFT JOIN admin a ON a.id = u.id
u.is_deleted = 0
AND u.role = #{userType}
AND u.status = #{status}
AND d.audit_status = #{auditStatus}
AND (u.username LIKE CONCAT('%', #{keyword}, '%') OR u.real_name LIKE CONCAT('%', #{keyword}, '%') OR u.phone LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY u.id DESC
